import React, { useState, useEffect } from "react";

function OrderList({ onSelect, onCreate, refreshTrigger }) {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("all");

  useEffect(() => {
    fetchOrders();
  }, [refreshTrigger, filter]);

  const fetchOrders = async () => {
    setLoading(true);
    try {
      const url = filter === "all"
        ? "http://127.0.0.1:5000/api/orders"
        : `http://127.0.0.1:5000/api/orders?status=${filter}`;
      const response = await fetch(url);
      const data = await response.json();
      setOrders(data);
    } catch (err) {
      console.error("Virhe haettaessa ordereita:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id, e) => {
    e.stopPropagation();
    if (!window.confirm("Haluatko varmasti poistaa Orderin?")) return;
    try {
      const response = await fetch(`http://127.0.0.1:5000/api/orders/${id}`, {
        method: "DELETE"
      });
      if (response.ok) {
        fetchOrders();
      } else {
        const data = await response.json();
        alert(data.error || "Poisto epäonnistui");
      }
    } catch (err) {
      alert("Virhe poistossa");
    }
  };

  const statusColor = (status) => {
    if (status === "Vapaa") return "#3b82f6";
    if (status === "Tripillä") return "#22c55e";
    return "#94a3b8";
  };

  return (
    <div>
      <div style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        marginBottom: "20px"
      }}>
        <h2 style={{ color: "#f97316", margin: 0 }}>📦 Orderit</h2>
        <button
          onClick={onCreate}
          style={{
            background: "#22c55e",
            color: "#fff",
            border: "none",
            padding: "10px 20px",
            borderRadius: "8px",
            cursor: "pointer",
            fontWeight: "600",
            fontSize: "14px"
          }}
        >
          + Uusi Order
        </button>
      </div>

      <div style={{ marginBottom: "16px", display: "flex", gap: "8px" }}>
        {["all", "Vapaa", "Tripillä"].map(f => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            style={{
              background: filter === f ? "#f97316" : "transparent",
              color: filter === f ? "#fff" : "#94a3b8",
              border: "1px solid #475569",
              padding: "6px 14px",
              borderRadius: "6px",
              cursor: "pointer",
              fontSize: "13px"
            }}
          >
            {f === "all" ? "Kaikki" : f}
          </button>
        ))}
      </div>

      {loading ? (
        <p style={{ color: "#94a3b8" }}>Ladataan...</p>
      ) : orders.length === 0 ? (
        <div style={{
          background: "rgba(255,255,255,0.03)",
          border: "1px dashed #475569",
          borderRadius: "12px",
          padding: "32px",
          textAlign: "center",
          color: "#94a3b8"
        }}>
          Ei ordereita. Luo uusi yllä olevasta napista.
        </div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
          {orders.map(order => (
            <div
              key={order.id}
              onClick={() => onSelect(order.id)}
              style={{
                background: "rgba(255,255,255,0.05)",
                border: "1px solid rgba(255,255,255,0.1)",
                borderRadius: "10px",
                padding: "16px 20px",
                cursor: "pointer",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                transition: "all 0.2s"
              }}
              onMouseEnter={(e) => e.currentTarget.style.borderColor = "#f97316"}
              onMouseLeave={(e) => e.currentTarget.style.borderColor = "rgba(255,255,255,0.1)"}
            >
              <div style={{ flex: 1 }}>
                <div style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "12px",
                  marginBottom: "6px"
                }}>
                  <span style={{
                    color: "#f97316",
                    fontWeight: "700",
                    fontSize: "15px"
                  }}>
                    {order.order_id}
                  </span>
                  <span style={{
                    background: statusColor(order.status),
                    color: "#fff",
                    padding: "2px 10px",
                    borderRadius: "12px",
                    fontSize: "11px",
                    fontWeight: "600"
                  }}>
                    {order.status}
                  </span>
                </div>
                <div style={{ color: "#cbd5e1", fontSize: "14px", marginBottom: "4px" }}>
                  {order.consignor_name || "—"} → {order.consignee_name || "—"}
                </div>
                <div style={{ color: "#94a3b8", fontSize: "13px" }}>
                  {order.goods_description || "Ei kuvausta"} ·{" "}
                  {order.weight} kg · {order.loading_meters} lm · {order.quantity} {order.pallet_type || "kpl"}
                </div>
              </div>
              <button
                onClick={(e) => handleDelete(order.id, e)}
                style={{
                  background: "transparent",
                  color: "#fca5a5",
                  border: "1px solid #7f1d1d",
                  padding: "6px 12px",
                  borderRadius: "6px",
                  cursor: "pointer",
                  fontSize: "12px"
                }}
              >
                Poista
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default OrderList;
